//! Haskell: the `azul` package (`target/codegen/haskell/`, generated by
//! `doc/src/codegen/v2/lang_haskell`).
//!
//! `Azul.Types` exposes every CSS value as a pure ADT - including the
//! monomorphized `CssPropertyValue<T>` aliases - with constructors named
//! `<Type>_<Variant>` (`T.CssProperty_Width (T.LayoutWidthValue_Exact ..)`,
//! C-like `T.LayoutDisplay_Flex`) and positional records (`T.ColorU 255 0 0 255`),
//! but not the api.json constructor functions. So the printer first turns
//! the IR's constructor calls into the data they build
//! ([`desugar_calls`](crate::codegen::lower::desugar_calls)) and prints
//! pure expressions; only `CssPropertyWithConditions` is a handle, built in
//! `IO` (`CssPropertyWithConditions.simple :: T.CssProperty -> IO ..`), so a
//! style is an `IO [CssPropertyWithConditions]`. A Vec (or `AzString`)
//! inside a value has no pure constructor: a limitation that drops the
//! property with a comment.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{EnumShape, Expr, Item, Module, Prim},
    lang::{
        escape_quoted, is_droppable_vec, item_comments, kept_items, swift::swift_camel,
        unicode_u4, ExprSyntax,
    },
    lower::desugar_calls,
    CodegenBackend, GeneratedFile,
};

/// The Haskell printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Haskell;

/// `(f a b)`; `f` alone without arguments.
fn app(f: String, args: Vec<Doc>, broken: bool) -> Doc {
    if args.is_empty() {
        return Doc::text(f);
    }
    let mut items = vec![Doc::text(f)];
    items.extend(args);
    Doc::list("(", items, " ", ")", false, broken, false)
}

impl ExprSyntax for Haskell {
    fn int(&self, value: i128, _ty: Prim) -> String {
        if value < 0 {
            format!("({value})")
        } else {
            value.to_string()
        }
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "(0 / 0)".to_string(),
            "inf" => "(1 / 0)".to_string(),
            "-inf" => "(-1 / 0)".to_string(),
            t if t.starts_with('-') => format!("({t})"),
            t => t.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        // record fields are CBool
        String::from(if b { "1" } else { "0" })
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("\"{}\"", escape_quoted(s, &[], &unicode_u4)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        // only the CssPropertyWithConditions IO constructors survive `desugar_calls`
        app(format!("{class}.{}", swift_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, _shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        app(format!("T.{ty}_{variant}"), args, broken)
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        app(
            format!("T.{ty}"),
            fields.into_iter().map(|(_, v)| v).collect(),
            broken,
        )
    }

    fn vec(&self, _ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        // unreachable below the top level: `limitation` rejects nested Vecs
        Doc::list("[", items, ", ", "]", false, broken, false)
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("(error {:?})", format!("not expressible: {what}")))
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Vec { ty, .. } if !is_droppable_vec(ty) => Some(format!(
                "a {ty} has no pure constructor in Azul.Types"
            )),
            Expr::Str(_) => Some("an AzString has no pure constructor in Azul.Types".to_string()),
            Expr::Call { class, method, .. } if class != "CssPropertyWithConditions" => {
                Some(format!("{class}::{method} is not in the Haskell API"))
            }
            _ => None,
        }
    }
}

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    let value = desugar_calls(&item.value);
    let desugared = Item {
        value: value.clone(),
        ..item.clone()
    };
    for line in &item_comments(&Haskell, &desugared) {
        out.push_str(&format!("-- {line}\n"));
    }
    let name = item.name.lower_camel();
    match &value {
        Expr::Vec { ty, items, .. } if is_droppable_vec(ty) => {
            let docs: Vec<Doc> = kept_items(&Haskell, ty, items)
                .into_iter()
                .map(|i| crate::codegen::lang::expr_doc(&Haskell, i))
                .collect();
            let broken = !docs.is_empty();
            let list = Doc::list("[", docs, ", ", "]", false, broken, false);
            out.push_str(&format!(
                "{name} :: IO [CssPropertyWithConditions]\n{name} = sequence\n  {}\n",
                render(&list, "  ", 1)
            ));
        }
        _ => out.push_str(&format!(
            "-- not expressible with the Haskell bindings: a {} value holds Vecs\n",
            item.ty
        )),
    }
    out
}

impl CodegenBackend for Haskell {
    fn lang(&self) -> &'static str {
        "haskell"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["hs"]
    }

    fn display_name(&self) -> &'static str {
        "Haskell"
    }

    fn extension(&self) -> &'static str {
        "hs"
    }

    fn emit_module(&self, m: &Module) -> String {
        let names: Vec<String> = m
            .items
            .iter()
            .filter(|i| is_droppable_vec(&i.ty))
            .map(|i| i.name.lower_camel())
            .collect();
        let mut out = format!(
            "-- Generated by azul-css codegen (Haskell). Do not edit by hand.\nmodule Styles ({}) \
             where\n\nimport Azul\nimport qualified Azul.Types as T\nimport qualified \
             Azul.CssPropertyWithConditions as CssPropertyWithConditions\n",
            names.join(", ")
        );
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from("module Main (main) where\n\nimport Styles\n\nmain :: IO ()\nmain = do\n");
        for item in m.items.iter().filter(|i| is_droppable_vec(&i.ty)) {
            let name = item.name.lower_camel();
            main.push_str(&format!(
                "  {name}Value <- {name}\n  putStrLn (\"{name}: \" ++ show (length {name}Value) ++ \" \
                 properties\")\n"
            ));
        }
        main.push_str("  pure ()\n");
        vec![
            GeneratedFile {
                path: "azul-styles.cabal".to_string(),
                contents: "cabal-version: 2.4\nname: azul-styles\nversion: 0.1.0\n\nexecutable \
                           azul-styles\n  main-is: Main.hs\n  other-modules: Styles\n  \
                           build-depends: base >= 4.14 && < 5, azul\n  default-language: \
                           Haskell2010\n  ghc-options: -threaded\n"
                    .to_string(),
            },
            GeneratedFile {
                path: "cabal.project".to_string(),
                contents: "-- Copy target/codegen/haskell/ to ./azul-haskell (azul.h into its \
                           cbits/),\n-- then: cabal run azul-styles --extra-lib-dirs=<dir of \
                           libazul>\npackages: .\noptional-packages: ./azul-haskell\n"
                    .to_string(),
            },
            GeneratedFile {
                path: "Styles.hs".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "Main.hs".to_string(),
                contents: main,
            },
        ]
    }
}
